/*SQL-ID : isry.csemd.mngrpage.aplcnttrprmng.mapper.AplcntTrprMngMapper selectAplyTrprDtlInfo : 신청자 정보(AFA100) 상세 */
SELECT A.TRPR_INFO_NO /* 대상자정보번호 */ ,A.APLY_RCPT_SN /* 신청접수일련번호 */ ,A.SRVC_EXCN_BIZ_NO /* 서비스실행사업번호 */ ,A.RSFR_INST_NO /* 자원제공기관번호 */ ,A.APLY_RCPT_CNTN_ID /* 신청접수접속아이디 */ ,A.RQST_PIC_YN /* 의뢰담당자여부 */ ,A.RCPT_RQST_COURS_SE_CD /* 접수의뢰경로구분코드 */ ,(SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'RCPT_RQST_COURS_SE_CD' AND CMMNS_CD_VALUE = A.RCPT_RQST_COURS_SE_CD ) AS RCPT_RQST_COURS_SE_NM /* 접수의뢰경로구분명 */ ,A.RQST_INST_NM /* 의뢰기관명 */ ,A.PIC_NM_ENCPT /* 담당자명[암호화] */ ,A.PIC_TELNO_ENCPT /* 담당자전화번호[암호화] */ ,A.PIC_MBL_TELNO_ENCPT /* 담당자휴대전화번호[암호화] */ ,A.PIC_EML_ADDR_ENCPT /* 이메일주소[암호화] */ ,A.TRPR_SRVY_RCPTN_MTHD_SE_CD /* 대상자설문수신방법구분코드 */ ,A.PRTCR_SRVY_RCPTN_MTHD_SE_CD /* 보호자설문수신방법구분코드 */ ,A.PIC_SRVY_RCPTN_MTHD_SE_CD /* 담당자설문수신방법구분코드 */ ,A.QUSTNB_SNDNG_YN /* 설문지발송여부 */ ,A.APLY_CN_MDFCN_PSBLTY_YN /* 신청내용수정가능여부 */ ,A.MDFCN_AUTHRT_DMND_YN /* 수정권한요청여부 */ ,A.PAPERS_SBMSN_SE_CD /* 서류제출구분코드 */ ,A.SPLMNT_PAPERS_NM /* 보완서류명 */ ,A.APLY_RCPT_SRNG_PRGRS_STTS_SE_CD /* 신청접수심사진행상태구분코드 */ ,A.TRPR_PHOTO_ATFINO /* 대상자사진첨부파일번호 */ ,A.APLY_PAPERS_ATFINO /* 신청서류첨부파일번호 */ ,A.HELP_DMND_CN /* 도움요청내용 */ ,A.DSCSN_EXPRNC_CN /* 상담경험내용 */ ,A.ENTSC_MTVTN_NCSSTY_CN /* 입교동기필요성내용 */ ,A.INTRVW_PTCPTN_SE_CD /* 면접참여구분코드 */ ,A.INTRVW_YMD /* 면접일자 */ ,A.INTRVW_HR /* 면접시간 */ ,A.INTRVW_PTCPTN_MTHD_SE_CD /* 면접참여방법구분코드 */ ,A.INTRVW_PLACE_VST_MTHD_SE_CD /* 면접장소방문방법구분코드 */ ,(SELECT APLY_RCPT_SRNG_PRGRS_STTS_SE_CD FROM ( SELECT * FROM AFA101 WHERE TRPR_INFO_NO = #{TRPR_INFO_NO} AND APLY_RCPT_SN = #{APLY_RCPT_SN} AND APLY_RCPT_SRNG_PRGRS_STTS_SE_CD LIKE '05%' ORDER BY FRST_REG_DT DESC ) WHERE ROWNUM <=1) AS INTRVW_RESULT /* 면접결과*/ ,A.RQST_CS_CN /* 의뢰사유내용 */ ,A.FAM_SITTN_CN /* 가족상황내용 */ ,A.INTRVW_SRNG_PIC_NM_ENCPT /* 면접심사담당자명[암호화] */ ,A.GHVR_OBSERV_INTRVW_PRTCLR_MATTER_CN /* 행동관찰면접특이사항내용 */ ,A.MTCLTN_LVING_RELATA_CN /* 입학생활관련내용 */ ,A.COGNZC_DEVLPA_SITTN_CN /* 인지발달상황내용 */ ,A.BDY_MIND_HEALTH_RELATA_CN /* 신체정신건강관련내용 */ ,A.INTERV_GENRVW_CN /* 면접관총평내용 */ ,A.DEPTHS_ARGMT_MATTER_CN /* 심층논의사항내용 */ ,A.YNGBGS_SCORE /* 청소년점수 */ ,A.PRTCR_SCORE /* 보호자점수 */ ,INTRVW_SRNG_GENRVW_CN /* 면접심사총평내용 */ ,A.CAMP_PTCPTN_PRTCR_MTVTN_SE_CD /* 캠프참여보호자동기구분코드 */ ,A.CAMP_PTCPTN_YNGBGS_MTVTN_SE_CD /* 캠프참여청소년동기구분코드 */ ,A.RPRS_MAAP_PROBM_SE_CD /* 대표주호소문제구분코드 */ ,A.MAAP_ETC_NM /* 주호소기타명 */ ,A.GHVR_CHARCT_CHAR_CN /* 행동성격특성내용 */ ,A.ETC_PRTCLR_MATTER_CN /* 기타특이사항내용 */ ,A.SCT_CN /* SCT내용 */ ,A.FRST_RGTR_ID /* 최초등록자아이디 */ ,TO_CHAR(A.FRST_REG_DT, 'YYYYMMDD') AS FRST_REG_DT /* 최초등록일시 */ ,A.LAST_MDFR_ID /* 최종수정자아이디 */ ,A.LAST_MDFCN_DT /* 최종수정일시 */ ,(SELECT APLY_RCPT_SRNG_PRGRS_STTS_SE_CD FROM AFA150 WHERE TRPR_INFO_NO = A.TRPR_INFO_NO AND APLY_RCPT_SN = A.APLY_RCPT_SN AND APLY_RCPT_SRNG_SE_CD = '05' ) AS SRNG_RESULT /* 심사결과 */
FROM AFA100 A WHERE A.TRPR_INFO_NO = #{TRPR_INFO_NO} /* 대상자정보번호 */ AND A.APLY_RCPT_SN = #{APLY_RCPT_SN} /* 신청접수일련번호 */


/*SQL-ID : isry.csemd.mngrpage.aplcnttrprmng.mapper.AplcntTrprMngMapper selectQustnbScoreEvlSttsInfo : 신청접수심사상태정보이력(AFA150) 설문지 점수 폼 라디오 버튼 상태 체크용(선정, 미선정, 반송) */

SELECT
   APLY_RCPT_SRNG_PRGRS_STTS_SE_CD
FROM AFA150     /* 신청접수심사상태정보이력 */

WHERE 1=1
AND TRPR_INFO_NO = #{TRPR_INFO_NO}
AND APLY_RCPT_SN = #{APLY_RCPT_SN}
AND APLY_RCPT_SRNG_SE_CD = #{CHK_APLY_RCPT_SRNG_SE_CD}


/*SQL-ID : isry.csemd.mngrpage.aplcnttrprmng.mapper.AplcntTrprMngMapper chkAplyRcptSrngPrgrsStts : 신청접수심사상태정보이력(AFA150) APLY_RCPT_SRNG_SE_CD 상태 값 체크 */

SELECT
   COUNT(*)
